package com.mycompany.greenbasket;
import java.io.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;
@WebServlet("/UpdateFarmerServlet") public class UpdateFarmerServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{Farmer f=new Farmer();f.setId(Integer.parseInt(r.getParameter("id")));f.setName(r.getParameter("name"));f.setFarmName(r.getParameter("farmName"));f.setEmail(r.getParameter("email"));f.setPassword(r.getParameter("password"));f.setMob(r.getParameter("mob"));f.setGender(r.getParameter("gender"));f.setAddress(r.getParameter("address"));f.setCity(r.getParameter("city"));f.setState(r.getParameter("state"));if(new FarmerDAO().updateFarmer(f)){r.getSession().setAttribute("loggedFarmer",f);s.sendRedirect(r.getContextPath()+"/welcomeFarmer.jsp");}else s.sendError(400,"Update failed");}catch(Exception e){s.sendError(400,"Invalid farmer information");}}}
